package com.teeniv.whatsapp;
import android.content.*;import android.net.Uri;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.activity.result.ActivityResultLauncher;import androidx.activity.result.contract.ActivityResultContracts;import androidx.annotation.NonNull;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import com.bumptech.glide.Glide;import com.google.firebase.auth.FirebaseAuth;import com.google.firebase.database.*;import com.google.firebase.storage.FirebaseStorage;import java.text.SimpleDateFormat;import java.util.*;
public class ChatActivity extends AppCompatActivity {
 String me,other,chatId;ArrayList<Message> messages=new ArrayList<>();MessageAdapter adapter;DatabaseReference msgRef;ValueEventListener listener;ActivityResultLauncher<String> photoPicker;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_chat);me=FirebaseAuth.getInstance().getUid();other=getIntent().getStringExtra("uid");String name=getIntent().getStringExtra("name"),photo=getIntent().getStringExtra("photo");chatId=me.compareTo(other)<0?me+"_"+other:other+"_"+me;((TextView)findViewById(R.id.recipientName)).setText(name==null?"Chat":name);ImageView av=findViewById(R.id.recipientAvatar);if(photo!=null&&!photo.isEmpty())Glide.with(this).load(photo).circleCrop().into(av);findViewById(R.id.backButton).setOnClickListener(v->finish());RecyclerView list=findViewById(R.id.messagesList);LinearLayoutManager lm=new LinearLayoutManager(this);lm.setStackFromEnd(true);list.setLayoutManager(lm);adapter=new MessageAdapter(messages,me);list.setAdapter(adapter);DatabaseReference chatRoot=FirebaseDatabase.getInstance().getReference("chats").child(chatId);chatRoot.child("participants").child(me).setValue(true);msgRef=chatRoot.child("messages");listener=msgRef.orderByChild("timestamp").addValueEventListener(new ValueEventListener(){public void onDataChange(DataSnapshot s){messages.clear();for(DataSnapshot d:s.getChildren()){Message m=d.getValue(Message.class);if(m!=null)messages.add(m);}adapter.notifyDataSetChanged();if(!messages.isEmpty())list.scrollToPosition(messages.size()-1);}public void onCancelled(DatabaseError e){toast(e.getMessage());}});findViewById(R.id.sendButton).setOnClickListener(v->{EditText input=findViewById(R.id.messageInput);String text=input.getText().toString().trim();if(!text.isEmpty()){send(text,"");input.setText("");}});photoPicker=registerForActivityResult(new ActivityResultContracts.GetContent(),uri->{if(uri!=null)uploadPhoto(uri);});findViewById(R.id.photoButton).setOnClickListener(v->photoPicker.launch("image/*"));}
 void send(String text,String image){String id=msgRef.push().getKey();if(id==null)return;Message m=new Message(id,me,text,image,System.currentTimeMillis());msgRef.child(id).setValue(m).addOnFailureListener(e->toast(e.getLocalizedMessage()));}
 void uploadPhoto(Uri uri){Toast.makeText(this,"Uploading photo…",Toast.LENGTH_SHORT).show();String path="chatPhotos/"+chatId+"/"+UUID.randomUUID()+".jpg";FirebaseStorage.getInstance().getReference(path).putFile(uri).addOnSuccessListener(t->t.getStorage().getDownloadUrl().addOnSuccessListener(url->send("",url.toString()))).addOnFailureListener(e->toast("Photo upload failed: "+e.getLocalizedMessage()));}
 @Override protected void onDestroy(){super.onDestroy();if(msgRef!=null&&listener!=null)msgRef.removeEventListener(listener);}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
class MessageAdapter extends RecyclerView.Adapter<MessageAdapter.Holder>{ArrayList<Message> data;String me;MessageAdapter(ArrayList<Message>d,String m){data=d;me=m;}public int getItemCount(){return data.size();}@NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.row_message,p,false));}public void onBindViewHolder(@NonNull Holder h,int i){Message m=data.get(i);boolean mine=me.equals(m.senderId);android.widget.LinearLayout.LayoutParams rp=(android.widget.LinearLayout.LayoutParams)h.bubble.getLayoutParams();rp.gravity=mine?Gravity.END:Gravity.START;h.bubble.setLayoutParams(rp);h.bubble.setBackgroundResource(mine?R.drawable.bubble_outgoing:R.drawable.bubble_incoming);h.text.setText(m.text==null?"":m.text);h.text.setVisibility(m.text==null||m.text.isEmpty()?View.GONE:View.VISIBLE);if(m.imageUrl!=null&&!m.imageUrl.isEmpty()){h.image.setVisibility(View.VISIBLE);com.bumptech.glide.Glide.with(h.image).load(m.imageUrl).into(h.image);}else h.image.setVisibility(View.GONE);h.time.setText(new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date(m.timestamp)));}static class Holder extends RecyclerView.ViewHolder{android.widget.LinearLayout bubble;TextView text,time;ImageView image;Holder(View v){super(v);bubble=v.findViewById(R.id.bubble);text=v.findViewById(R.id.messageText);time=v.findViewById(R.id.messageTime);image=v.findViewById(R.id.messageImage);}}}
